<style>
@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@500;600;700&family=Barlow:wght@400;500;600;700&display=swap');
:root{--xred:#e21a0b;--xink:#202020;--xgray:#f3f3f1;--xmuted:#727272}.xd20-page{font-family:Barlow,Arial,sans-serif;color:var(--xink);background:#fff}.xd20-container{width:min(1240px,calc(100% - 40px));margin:auto}.foot-header{background:#fff;color:var(--xink);border-bottom:1px solid #e5e5e5}.foot-header__masthead{background:#252525;padding:8px 0}.foot-brand{color:#fff}.foot-brand__monogram{border-color:var(--xred);color:#fff;background:var(--xred)}.foot-brand strong{font-family:'Barlow Condensed',sans-serif;font-size:27px;text-transform:uppercase}.foot-header__account button,.foot-header__account a{color:#fff}.foot-navigation{border-radius:0;box-shadow:none;transform:none;left:0;top:0;width:100%;position:relative;padding:0;justify-content:flex-start;min-height:66px}.foot-navigation a{font-family:'Barlow Condensed',sans-serif;font-size:18px;padding:18px}.foot-navigation a:hover{color:var(--xred)}.foot-navigation-wrap{height:auto}.foot-hero{display:none}.xd20-hero__slide{display:none;position:relative;min-height:650px;color:#fff}.xd20-hero__slide.is-active{display:block}.xd20-hero__slide>img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}.xd20-hero__slide>div:nth-child(2){position:absolute;inset:0;background:linear-gradient(90deg,rgba(0,0,0,.7),rgba(0,0,0,.18))}.xd20-hero__copy{position:relative;display:flex;min-height:650px;max-width:1240px;flex-direction:column;justify-content:center;align-items:flex-start}.xd20-hero__copy p:first-child,.xd20-copy>p,.xd20-heading>p,.xd20-split__copy>p{margin:0 0 13px;color:var(--xred);font-weight:700;text-transform:uppercase}.xd20-hero__copy h1{max-width:650px;margin:0;font:700 clamp(44px,6vw,70px)/1.03 'Barlow Condensed',sans-serif;text-transform:uppercase}.xd20-hero__copy p{max-width:620px;font-size:18px;line-height:1.6}.xd20-button{display:inline-flex;gap:10px;align-items:center;margin-top:20px;padding:14px 21px;background:var(--xred);color:#fff;font-weight:700;text-decoration:none;text-transform:uppercase}.xd20-quality{padding:56px 0}.xd20-quality>.xd20-container{display:grid;grid-template-columns:repeat(5,1fr);gap:18px}.xd20-quality article{min-height:160px;padding:24px;border:1px solid #dedede;text-align:center}.xd20-quality i{display:block;margin-bottom:13px;color:var(--xred);font-size:38px}.xd20-quality h3{margin:0;font:700 22px/1.05 'Barlow Condensed',sans-serif;text-transform:uppercase}.xd20-quality p{margin:8px 0 0;color:var(--xmuted);font-size:14px}.xd20-section{padding:100px 0}.xd20-about{display:grid;grid-template-columns:1fr 1.05fr;gap:70px;align-items:center}.xd20-about__image{position:relative}.xd20-about__image img{width:100%;height:500px;object-fit:cover}.xd20-about__image strong{position:absolute;top:45px;right:-25px;padding:22px;background:var(--xred);color:#fff;font:700 55px 'Barlow Condensed',sans-serif}.xd20-about__image small{display:block;font:600 15px Barlow,sans-serif;text-transform:uppercase}.xd20-copy h2,.xd20-split h2,.xd20-heading h2{margin:0 0 20px;font:700 clamp(40px,5vw,62px)/1.05 'Barlow Condensed',sans-serif;text-transform:uppercase}.xd20-copy>div,.xd20-split__copy>div,.xd20-heading>div{color:#555;font-size:18px;line-height:1.65}.xd20-copy ul,.xd20-split ul{display:grid;grid-template-columns:repeat(2,1fr);gap:12px;padding:0;list-style:none}.xd20-copy li,.xd20-split li{color:#686868}.xd20-copy i{margin-right:8px;color:var(--xred)}.xd20-split{display:grid;grid-template-columns:1fr 1fr;background:var(--xred);color:#fff}.xd20-split__copy{padding:88px max(30px,calc((100vw - 1240px)/2));padding-right:80px}.xd20-split__copy>p{color:#fff}.xd20-split__copy>div,.xd20-split li{color:#fff}.xd20-split ul{grid-template-columns:1fr}.xd20-split img{width:100%;height:100%;min-height:500px;object-fit:cover}.xd20-section--gray{background:var(--xgray)}.xd20-heading{display:grid;grid-template-columns:1.1fr 1fr;gap:35px;align-items:start;margin-bottom:36px}.xd20-heading p{grid-column:1/-1}.xd20-rail{display:grid;grid-auto-flow:column;grid-auto-columns:calc((100% - 48px)/3);gap:24px;overflow-x:auto;scroll-snap-type:x mandatory;padding-bottom:16px}.xd20-rail article{scroll-snap-align:start}.xd20-rail a{display:block;color:var(--xink);text-decoration:none}.xd20-rail img{width:100%;aspect-ratio:1.1;object-fit:cover}.xd20-rail h3{margin:12px 0;font:700 25px 'Barlow Condensed',sans-serif;text-transform:uppercase}.xd20-team{display:grid;grid-template-columns:repeat(4,1fr);gap:24px}.xd20-team img{width:100%;aspect-ratio:.9;object-fit:cover;background:#eee}.xd20-team h3{margin:14px 0 2px;font:600 29px 'Barlow Condensed',sans-serif;text-align:center}.xd20-team p{margin:0;color:var(--xred);font-size:14px;font-weight:700;text-align:center;text-transform:uppercase}.xd20-partners{padding:72px 0;text-align:center}.xd20-partners h2{margin:0 0 34px;font:700 48px 'Barlow Condensed',sans-serif;text-transform:uppercase}.xd20-partners>div>div{display:flex;gap:16px;overflow-x:auto}.xd20-partners a{display:grid;flex:0 0 150px;place-items:center;height:105px;border:1px solid #e2e2e2}.xd20-partners img{max-width:120px;max-height:70px}.foot-footer{background:#222}.foot-footer__top{display:none}.foot-footer__grid{grid-template-columns:1.35fr 1fr 1fr 1.2fr}.foot-footer__grid h3{font-family:'Barlow Condensed',sans-serif;font-size:22px}.foot-footer__grid a:hover{color:var(--xred)}.foot-footer__newsletter button{background:var(--xred)}
@media(max-width:800px){.foot-navigation{display:none}.foot-navigation.is-open{display:flex;flex-direction:column}.foot-mobile-toggle{display:block;width:100%;padding:12px;background:#222;color:#fff;border:0}.xd20-hero__slide,.xd20-hero__copy{min-height:560px}.xd20-quality>.xd20-container{grid-template-columns:repeat(2,1fr)}.xd20-about,.xd20-split{grid-template-columns:1fr}.xd20-about{gap:35px}.xd20-about__image strong{right:15px}.xd20-split__copy{padding:60px 30px}.xd20-heading{grid-template-columns:1fr}.xd20-rail{grid-auto-columns:82%}.xd20-team{grid-template-columns:repeat(2,1fr)}.foot-footer__grid{grid-template-columns:1fr 1fr}}
</style>
